function drawSource() { if (!state.image) return; const img=state.image; const iw=img.videoWidth||img.naturalWidth||img.width,ih=img.videoHeight||img.naturalHeight||img.height;if(!iw||!ih)return;const {top,bottom,left,right}=state.crop; const sx=iw*left/100,sy=ih*top/100,sw=iw*(1-(left+right)/100),sh=ih*(1-(top+bottom)/100);const scale=Math.min(1,960/sw,960/sh);const c=$('previewCanvas');c.width=Math.max(1,Math.round(sw*scale));c.height=Math.max(1,Math.round(sh*scale));ctx.drawImage(img,sx,sy,sw,sh,0,0,c.width,c.height);drawHistogram();if($('cropDialog').open)drawCrop(); }
function drawHistogram() { const c=$('previewCanvas'); const pixels=ctx.getImageData(0,0,c.width,c.height).data;const bins=new Array(64).fill(0);let bright=0,dark=0,count=0;for(let i=0;i<pixels.length;i+=16){const r=pixels[i],g=pixels[i+1],b=pixels[i+2];const y=.2126*r+.7152*g+.0722*b;bins[Math.min(63,Math.floor(y/4))]++;if(Math.max(r,g,b)>=250)bright++;if(y<=5)dark++;count++;}histCtx.clearRect(0,0,640,72);const max=Math.max(1,...bins);histCtx.fillStyle='#b6c49a';for(let i=0;i<64;i++){const h=(bins[i]/max)*62;histCtx.fillRect(i*10+1,72-h,7,h);}histCtx.strokeStyle='#3c4632';histCtx.beginPath();histCtx.moveTo(0,71);histCtx.lineTo(640,71);histCtx.stroke();$('clipStats').textContent=`Near white ${(bright/count*100).toFixed(1)}% · dark ${(dark/count*100).toFixed(1)}%`; }
async function setImage(data,source,timestamp=Date.now()){const generation=state.sourceGeneration,sequence=++state.decodeSequence;const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('This preview could not be decoded.'));image.src=data;});if(generation!==state.sourceGeneration||sequence<state.lastImageSequence)return false;state.lastImageSequence=sequence;state.image=image;state.source=source;state.timestamp=timestamp;drawSource();updateSourceLabels();return true;}
function updateSourceLabels(){const badge=$('sourceBadge');const live=state.source==='sony'||state.source==='video'||state.source==='camera';const stale=live&&(!state.visible||Date.now()-state.timestamp>5000);const kept=state.source==='sony'&&stale;badge.textContent=state.source==='none'?'NO FEED':state.source==='sample'?'SAMPLE · NOT LIVE':state.source==='photo'?'PHOTO · NOT LIVE':kept?'LAST SONY FRAME':stale?'PREVIEW PAUSED':'LIVE INPUT';badge.classList.toggle('live',live&&!stale);badge.classList.toggle('paused',stale);$('emptyPreview').hidden=state.source!=='none';$('previewFooter').hidden=state.source==='none';$('stopButton').disabled=!live&&state.captureState!=='capturing';$('frameLabel').textContent=state.source==='camera'?'LIVE FROM YOUR a6100 · CAMERA WI-FI':state.source==='sony'?'SHARED SONY APP · CROP YOUR VIEW':state.source==='video'?'SELECTED VIDEO INPUT':state.source==='sample'?'ILLUSTRATED SAMPLE · LOCAL GUIDANCE ONLY':'IMPORTED PHOTO';$('frameAge').textContent=live?`${Math.max(0,Math.floor((Date.now()-state.timestamp)/1000))}s since frame`:'NOT A CAMERA CONNECTION';$('sourceDescription').textContent=state.source==='camera'?'Direct from your camera':state.source==='sony'?'Open Sony to refresh the frame':state.source==='video'?'Verify you selected your camera feed':'Preview stays on your device';}
