function stopCapture(){stopLiveAI();state.sourceGeneration++;if(native&&state.cameraRequested){state.cameraRequested=false;try{window.Android.cameraDisconnect();}catch{}}state.captureState='idle';state.visible=false;if(state.stream){state.stream.getTracks().forEach(t=>t.stop());state.stream=null;}if(state.video){state.video.srcObject=null;state.video=null;}if(state.source==='sony'||state.source==='video'||state.source==='camera'){state.source='photo';invalidate('Capture stopped. The last frame is a still reference; ask for a fresh suggestion.');status('Capture stopped. The last local frame remains for reference.');}updateSourceLabels();}
