async function connectVideo(){if(!navigator.mediaDevices?.getUserMedia)throw new Error('Video input is unavailable here. Open the local app in Chrome or Edge.');stopCapture();const generation=state.sourceGeneration;const id=$('videoDevice').value;const stream=await navigator.mediaDevices.getUserMedia({video:id?{deviceId:{exact:id},width:{ideal:1280},height:{ideal:720}}:{width:{ideal:1280},height:{ideal:720}},audio:false});if(generation!==state.sourceGeneration){stream.getTracks().forEach(t=>t.stop());return;}const video=document.createElement('video');video.muted=true;video.playsInline=true;video.srcObject=stream;await video.play();if(generation!==state.sourceGeneration){stream.getTracks().forEach(t=>t.stop());video.srcObject=null;return;}state.visible=true;state.stream=stream;state.video=video;state.image=video;state.source='video';state.crop={top:0,bottom:0,left:0,right:0};invalidate('Video input connected. Enter the settings shown on your a6100.');$('setupDialog').close();const devices=await navigator.mediaDevices.enumerateDevices();if(generation!==state.sourceGeneration)return;$('videoDevice').replaceChildren(new Option('Default camera input',''));for(const device of devices.filter(d=>d.kind==='videoinput'))$('videoDevice').add(new Option(device.label||'Video input',device.deviceId));$('videoDevice').value=stream.getVideoTracks()[0].getSettings().deviceId||'';stream.getVideoTracks()[0].addEventListener('ended',()=>{stopCapture();status('The video input disconnected.');});}
