function drawCrop(){if(!state.image)return;const c=$('cropCanvas'),cctx=c.getContext('2d');const img=state.image;const w=img.videoWidth||img.naturalWidth,h=img.videoHeight||img.naturalHeight;if(!w||!h)return;c.width=Math.min(640,w);c.height=Math.round(c.width*h/w);cctx.drawImage(img,0,0,c.width,c.height);const x=c.width*Number($('cropLeft').value)/100,y=c.height*Number($('cropTop').value)/100,r=c.width*(1-Number($('cropRight').value)/100),b=c.height*(1-Number($('cropBottom').value)/100);cctx.fillStyle='#101609aa';cctx.fillRect(0,0,c.width,y);cctx.fillRect(0,b,c.width,c.height-b);cctx.fillRect(0,y,x,b-y);cctx.fillRect(r,y,c.width-r,b-y);cctx.strokeStyle='#d6ee94';cctx.lineWidth=2;cctx.strokeRect(x,y,r-x,b-y);}
$('cropButton').onclick=()=>{if(state.source==='none'){toast('Connect a feed or open a sample first.');return;}for(const key of Object.keys(state.crop)){const id='crop'+key[0].toUpperCase()+key.slice(1);$(id).value=state.crop[key];$(id+'Value').value=state.crop[key]+'%';}$('cropDialog').showModal();drawCrop();};
for(const key of Object.keys(state.crop)){const id='crop'+key[0].toUpperCase()+key.slice(1);$(id).oninput=()=>{$(id+'Value').value=$(id).value+'%';drawCrop();};}
