function canAnalyze(){if(state.source==='none')throw new Error('Connect a feed or open a photo before asking AI.');if(state.source==='sample')throw new Error('The sample is an illustration. Use local guidance, or connect a real feed for AI.');if(!state.aiConfigured){openSetup('ai');throw new Error('Connect your own API key first.');}if(state.source==='video'&&(!state.visible||Date.now()-state.timestamp>5000))throw new Error('The feed is paused. Wait for a fresh frame.');if(state.source==='camera'&&Date.now()-state.timestamp>5000)throw new Error('The camera picture is not updating. Check the camera connection.');if(state.source==='sony'&&!state.timestamp)throw new Error('No Sony frame yet. Open Sony, start remote shooting, then come back.');}
