function addWarning(message){const p=document.createElement('p');p.className='warning';p.textContent=message;$('warnings').append(p);}
function renderRecommendation(rec,input,scene=null){state.rec={...rec,input,scene,at:Date.now(),frameAt:state.timestamp,revision:state.revision};$('suggestionTitle').textContent=rec.title;$('suggestionSubtitle').textContent=rec.status==='unmetered'?'Creative starting points. Enter the camera meter reading to calculate ISO.':rec.status==='conflict'?'Your constraints need a tradeoff. Check the notes before changing settings.':'Calculated from the camera readings you entered. Confirm with a test shot.';$('recommendationBadge').textContent=rec.status==='metered'?'METER-BASED STARTING POINT':rec.status==='conflict'?'TRADEOFF NEEDED':'EXPOSURE NOT METERED';$('settingsCards').replaceChildren();$('warnings').replaceChildren();for(const key of ['shutter','aperture','iso']){const value=rec.settings[key],locked=state.locks[key],unknown=value===null;const card=document.createElement('div');card.className='setting-card'+(unknown?' needs-meter':'');const head=document.createElement('div');head.className='setting-top';const label=document.createElement('label');const check=document.createElement('input');check.type='checkbox';check.dataset.setting=key;check.disabled=locked||unknown;check.checked=!locked&&!unknown;check.setAttribute('aria-label','Select suggested '+key);label.append(check,document.createTextNode(key.toUpperCase()));head.append(label);if(locked){const lock=document.createElement('span');lock.className='setting-lock';lock.textContent='◆ LOCKED';head.append(lock);}const val=document.createElement('div');val.className='setting-value';val.textContent=unknown?'Needs meter':key==='shutter'?formatShutter(value):key==='aperture'?`ƒ/${value}`:String(value);const current=document.createElement('div');current.className='setting-current';current.textContent='CURRENT '+(key==='shutter'?formatShutter(input.current[key]):key==='aperture'?'ƒ/'+input.current[key]:input.current[key]);const reason=document.createElement('p');reason.className='setting-reason';reason.textContent=rec.reasons[key];card.append(head,val,current,reason);card.classList.toggle('selected',check.checked);check.onchange=()=>{card.classList.toggle('selected',check.checked);updateSelection();};$('settingsCards').append(card);}for(const warning of rec.warnings)addWarning(warning);if(rec.exposureErrorEV!=null&&Math.abs(rec.exposureErrorEV)>.18)addWarning(`This combination is ${Math.abs(rec.exposureErrorEV).toFixed(2)} EV ${rec.exposureErrorEV>0?'brighter':'darker'} than your requested metered target.`);if(state.source==='sample')addWarning('Illustrated sample: these are settings examples, not a measurement of a real scene.');if(scene){$('sceneReading').replaceChildren();const tag=document.createElement('span');tag.textContent='AI SCENE READING · FRAME '+new Date(state.rec.frameAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});const text=document.createElement('div');text.textContent=scene.summary;$('sceneReading').append(tag,text);for(const item of [...scene.observations,...scene.limitations]){const p=document.createElement('p');p.textContent=item;$('sceneReading').append(p);}$('sceneReading').hidden=false;}else $('sceneReading').hidden=true;$('focusAdvice').textContent=rec.focus;$('wbAdvice').textContent=rec.whiteBalance;$('secondaryAdvice').hidden=false;$('decisionBar').hidden=false;$('copyButton').disabled=false;if($('quickPlan')){$('quickShutter').textContent=formatShutter(rec.settings.shutter);$('quickAperture').textContent='ƒ/'+rec.settings.aperture;$('quickISO').textContent=rec.settings.iso===null?'ISO needs meter':'ISO '+rec.settings.iso;$('quickPlan').hidden=false;}updateSelection();}
function updateSelection(){
  const selected=[...document.querySelectorAll('[data-setting]:checked')].map(x=>x.dataset.setting);
  const count=selected.length;
  $('confirmButton').disabled=!count||!state.rec;
  $('confirmButton').textContent=count?`I changed ${count===1?'this setting':`these ${count} settings`} ✓`:'Select a setting above';
  $('selectionWarning')?.remove();
  if(!state.rec||!count)return;
  const rec=state.rec,actual={...rec.input.current};
  for(const key of selected)if(!state.locks[key]&&rec.settings[key]!=null)actual[key]=rec.settings[key];
  const notes=[];
  if(rec.input.meteringEV!==null){
    const error=rec.input.meteringEV+Math.log2(actual.iso/rec.input.current.iso)+Math.log2(actual.shutter/rec.input.current.shutter)-2*Math.log2(actual.aperture/rec.input.current.aperture)-rec.input.exposureBias;
    if(Math.abs(error)>.18)notes.push(`Your selected changes alone leave the camera about ${Math.abs(error).toFixed(2)} EV ${error>0?'brighter':'darker'} than the requested meter target. The exposure calculation depends on the combination of settings.`);
  }
  const planDiffers=['shutter','aperture','iso'].some(key=>rec.settings[key]!=null&&Math.abs(actual[key]-rec.settings[key])>1e-9);
  if(planDiffers){
    const check=recommend({...rec.input,current:actual,locks:{shutter:true,aperture:true,iso:true},meteringEV:null},rec.scene);
    notes.push(...check.warnings.filter(message=>/locked shutter|locked aperture|locked ISO/.test(message)));
  }
  if(notes.length){const p=document.createElement('p');p.id='selectionWarning';p.className='warning';p.textContent=notes.join(' ');$('warnings').append(p);}
}
function scrollSuggestions(){document.querySelector('.suggestions')?.scrollIntoView({behavior:'smooth',block:'start'});}
if($('quickReview'))$('quickReview').onclick=scrollSuggestions;
function runLocal(){try{const input=getInput();const rec=recommend(input);renderRecommendation(rec,input);scrollSuggestions();status('Local guidance ready. Review each suggestion before changing your camera.');}catch(e){toast(e.message);status('Check your camera and lens entries.');}}
async function requestAnalysis(image,context){if(native){const id=String(Date.now())+'-'+Math.random().toString(36).slice(2);return new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{state.pending.delete(id);reject(new Error('AI took too long. Try again, or use local guidance.'));},75000);state.pending.set(id,{resolve,reject,timeout});try{window.Android.analyze(image,JSON.stringify(context),id);}catch(e){clearTimeout(timeout);state.pending.delete(id);reject(e);}});}const response=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image,context,consent:true}),signal:AbortSignal.timeout(40000)});const result=await response.json();if(!response.ok)throw new Error(result.error||'AI request failed.');return result.scene;}
window.onNativeAnalysis=(id,payload)=>{const pending=state.pending.get(id);if(!pending)return;state.pending.delete(id);clearTimeout(pending.timeout);try{const result=typeof payload==='string'?JSON.parse(payload):payload;if(result.error)pending.reject(new Error(result.error));else pending.resolve(result.scene);}catch(e){pending.reject(e);}};
async function runAI(periodic=false){if(state.busy)return;try{canAnalyze();const input=getInput();recommend(input);const revision=state.revision;const capturedAt=state.timestamp,sourceGeneration=state.sourceGeneration;state.busy=true;$('suggestButton').disabled=true;status('Reading the cropped frame… Your camera settings stay in your hands.');const image=$('previewCanvas').toDataURL('image/jpeg',.78);const scene=await requestAnalysis(image,{camera:$('cameraBody').value||'Sony a6100',cameraModel:state.cameraModel||null,connection:state.cameraKind||null,...input,lensLabel:$('lensName').selectedOptions[0].text,intent:$('intent').value,source:state.source,captureAgeSeconds:Math.max(0,(Date.now()-capturedAt)/1000),history:summarizeHistory(loadHistory(localStorage))});if(revision!==state.revision||sourceGeneration!==state.sourceGeneration||(state.source==='video'&&!state.visible)){status('Settings or source changed during analysis. Ask for a fresh reading.');return;}if(!scene||typeof scene.summary!=='string'||!Array.isArray(scene.observations)||!Array.isArray(scene.limitations))throw new Error('AI returned an incomplete scene reading.');renderRecommendation(recommend(input,scene),input,scene);state.rec.frameAt=capturedAt;const frameTag=$('sceneReading').querySelector('span');if(frameTag)frameTag.textContent='AI SCENE READING · FRAME '+new Date(capturedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'});const camSettings=state.source==='camera'&&Date.now()-(state.cameraSettingsAt||0)<10000?state.cameraSettings:null;addEntry(localStorage,makeEntry({input,camera:camSettings,scene,source:state.source}));renderHistory();if(!periodic)scrollSuggestions();status('Scene reading ready. Review suggestions and confirm with a test shot.');}catch(e){stopLiveAI();logJs('ai',e.message);status(e.message);toast(e.message);}finally{state.busy=false;$('suggestButton').disabled=false;}}
function selectValue(id,value){const el=$(id);if(el.tagName==='SELECT'&&![...el.options].some(o=>Number(o.value)===value))el.add(new Option(id==='currentShutter'?formatShutter(value):String(value),String(value)));el.value=String(value);}
function planText(){if(!state.rec)return '';const r=state.rec;const lines=['Framewise · '+($('cameraBody').value||'Sony a6100'),r.title,'Suggested starting settings:',`Shutter ${formatShutter(r.settings.shutter)} · Aperture ƒ/${r.settings.aperture} · ISO ${r.settings.iso??'needs camera meter'}`,`Focus: ${r.focus}`,`White balance: ${r.whiteBalance}`,...r.warnings,'Apply settings manually and verify a test shot.'];return lines.join('\n');}
$('copyButton').onclick=async()=>{try{const text=planText();if(native)window.Android.copyText(text);else await navigator.clipboard.writeText(text);toast('Settings plan copied.');}catch{toast('Clipboard unavailable in this browser.');}};
$('confirmButton').onclick=()=>{if(!state.rec||state.rec.revision!==state.revision)return;const selected=[...document.querySelectorAll('[data-setting]:checked')].map(x=>x.dataset.setting);if(!selected.length)return;const rec=state.rec;for(const key of selected)if(!state.locks[key]&&rec.settings[key]!=null)selectValue({shutter:'currentShutter',aperture:'currentAperture',iso:'currentISO'}[key],rec.settings[key]);const text=selected.map(key=>`${key==='iso'?'ISO':key[0].toUpperCase()+key.slice(1)} ${key==='shutter'?formatShutter(rec.settings[key]):key==='aperture'?'ƒ/'+rec.settings[key]:rec.settings[key]}`).join(' · ');state.log.unshift({at:Date.now(),text});state.log=state.log.slice(0,20);try{localStorage.setItem('framewise.log',JSON.stringify(state.log));}catch{}$('meterEV').value='';renderLog();invalidate('Camera values updated from your confirmation. Re-enter the meter reading for the next shot.');status('Recorded your changes. Recheck the camera meter and a test shot.');toast('Recorded. Read the meter again before your next suggestion.');};
function renderLog(){$('logCount').textContent=`${state.log.length} decision${state.log.length===1?'':'s'}`;$('sessionLog').replaceChildren();if(!state.log.length){const p=document.createElement('p');p.className='micro';p.textContent='Confirmed choices will appear here. Images and API keys are never saved in this log.';$('sessionLog').append(p);}for(const entry of state.log){const div=document.createElement('div');div.className='session-entry';const time=document.createElement('time');time.textContent=new Date(entry.at).toLocaleString();const p=document.createElement('p');p.textContent=entry.text;div.append(time,p);$('sessionLog').append(div);}}
$('clearLog').onclick=()=>{state.log=[];try{localStorage.removeItem('framewise.log');}catch{}renderLog();};renderLog();
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopLiveAI('Live AI paused while the app was hidden.');});
setInterval(()=>{if(state.video&&!state.video.paused){state.image=state.video;state.timestamp=Date.now();drawSource();}updateSourceLabels();},1000);
// Paint the clearly disconnected opening view without presenting it as a camera frame.
const background=new Image();background.onload=()=>{if(state.source==='none'){ctx.drawImage(background,0,0,960,600);}};background.src='demo.svg';
function parseReleaseNotes(text){const lines=String(text||'').split(/^-{3,}\s*$/m)[0].split(/\r?\n/).map(l=>l.trim()).filter(l=>l&&!/^versionCode\s*[:=]/i.test(l));const bullets=lines.filter(l=>/^[-*•]\s+/.test(l)).map(l=>l.replace(/^[-*•]\s+/,'').replace(/\*\*/g,''));const extra=lines.filter(l=>!/^[-*•]\s+/.test(l)&&!/^#/.test(l)).map(l=>l.replace(/\*\*/g,''));return {bullets,extra};}
function renderNotes(el,title,text){const notes=parseReleaseNotes(text);el.replaceChildren();if(!notes.bullets.length&&!notes.extra.length){el.hidden=true;return;}const h=document.createElement('h3');h.textContent=title;el.append(h);if(notes.bullets.length){const ul=document.createElement('ul');for(const b of notes.bullets){const li=document.createElement('li');li.textContent=b;ul.append(li);}el.append(ul);}for(const x of notes.extra){const p=document.createElement('p');p.className='micro';p.textContent=x;el.append(p);}el.hidden=false;}
function renderSections(el,sections){el.replaceChildren();const h=document.createElement('h3');h.textContent=`What’s new in the ${sections.length} updates you’ll get`;el.append(h);for(const sec of sections){const notes=parseReleaseNotes(String(sec.notes||'').split(/^### Also in/m)[0]);const v=document.createElement('p');v.className='notes-version';v.textContent='Framewise '+String(sec.version).replace(/^v/,'');el.append(v);const ul=document.createElement('ul');for(const b of notes.bullets){const li=document.createElement('li');li.textContent=b;ul.append(li);}el.append(ul);}el.hidden=false;}
function applyUpdateStatus(update){if(!update||!$('updateStatus'))return;if(update.currentVersion)$('appVersion').textContent='Framewise '+update.currentVersion;if(update.message)$('updateStatus').textContent=update.message;if(update.latestVersion)state.updateVersion=update.latestVersion;if(update.url)state.updateUrl=update.url;if(typeof update.notes==='string'&&update.notes)state.updateNotes=update.notes;if(Array.isArray(update.notesByVersion)&&update.notesByVersion.length)state.updateSections=update.notesByVersion;if(state.updateSections&&state.updateSections.length>1)renderSections($('updateNotes'),state.updateSections);else if(state.updateNotes&&state.updateVersion)renderNotes($('updateNotes'),`What’s new in ${state.updateVersion}`,state.updateNotes);const offer=['available','permission'].includes(update.state)||(update.state==='error'&&state.updateVersion);$('installUpdateButton').hidden=!offer;$('installUpdateButton').textContent=state.updateVersion?`Install Framewise ${state.updateVersion}`:'Install update';$('releasePageButton').hidden=!state.updateUrl;$('checkUpdateButton').disabled=['checking','downloading','verifying','installing'].includes(update.state);$('installUpdateButton').disabled=$('checkUpdateButton').disabled;if(['current','installed'].includes(update.state))$('updateNotes').hidden=true;if(update.state==='available'&&state.updateVersion){$('updateBanner').hidden=false;$('updateBannerText').textContent=`Framewise ${state.updateVersion} is ready. See what’s new.`;}if(['installing','installed','current'].includes(update.state))$('updateBanner').hidden=true;}
// ---- Direct camera connection (Sony Camera Remote API over the camera's own Wi-Fi)
function applyCameraSettings(cam){if(!cam||!$('cameraAutofill').checked)return false;let changed=false;if(Number.isFinite(cam.shutter)&&Math.abs(Number($('currentShutter').value)-cam.shutter)>1e-9){selectValue('currentShutter',cam.shutter);changed=true;}if(Number.isFinite(cam.aperture)&&Number($('currentAperture').value)!==cam.aperture){$('currentAperture').value=String(cam.aperture);changed=true;}if(Number.isFinite(cam.iso)&&Number($('currentISO').value)!==cam.iso){selectValue('currentISO',cam.iso);changed=true;}if(changed){$('meterEV').value='';invalidate('Camera settings changed on the camera. Ask for a fresh suggestion.');}return changed;}
function cameraButtons(connected){if(!$('cameraConnectButton'))return;$('cameraConnectButton').disabled=connected;$('cameraDisconnectButton').disabled=!connected;}
function connectCamera(kind){if(!native)return;kind=typeof kind==='string'?kind:'sony-wifi';stopCapture();state.timestamp=0;state.cameraFrameTs=0;state.cameraSettingsTs=0;state.cameraLastStep='';state.cameraRequested=true;state.cameraKind=kind;if(kind==='usb'){window.Android.cameraConnectUsb();}else if(kind==='canon-wifi'){window.Android.cameraConnectCanonWifi($('canonIp').value.trim());}else{const pw=$('cameraPassword').value;window.Android.cameraConnect($('cameraSsid').value.trim(),pw,$('cameraRemember').checked);$('cameraPassword').value='';if($('cameraRemember').checked&&pw)$('cameraPassword').placeholder='Saved on this phone';}cameraButtons(true);invalidate('Connecting to your camera…');status('Connecting to your camera…');}
async function pollCamera(){if(!native||!state.cameraRequested)return;let cam;try{cam=parseNative('cameraStatus',String(state.cameraFrameTs||0));}catch(e){return;}if(cam.step&&cam.step!==state.cameraLastStep){state.cameraLastStep=cam.step;status(cam.step);if($('cameraStatus'))$('cameraStatus').textContent=cam.step;}if(cam.model&&cam.model!==state.cameraModel){state.cameraModel=cam.model;const body=/2000D|Rebel T7|Kiss X90|Canon/i.test(cam.model)?'Canon EOS 2000D':/6100|ILCE|Sony/i.test(cam.model)?'Sony a6100':null;if(body&&$('cameraBody').value!==body){$('cameraBody').value=body;if(body.startsWith('Canon')&&$('lensName').value!=='canon-kit')$('lensName').value='canon-kit';savePreferences();if(typeof showKind==='function')showKind();}}if(cam.state==='error'){jsLog.push({at:Date.now(),area:cam.kind||'camera',message:String(cam.error||cam.step||'connection stopped').slice(0,1000)});if(jsLog.length>100)jsLog.shift();}if(cam.state==='error'||cam.state==='idle'){state.cameraRequested=false;cameraButtons(false);if(cam.state==='error')toast(cam.error||cam.step||'The camera connection stopped.');if(state.source==='camera'){state.sourceGeneration++;state.source='photo';invalidate('The camera connection stopped. The last frame is a still reference.');}updateSourceLabels();return;}if(cam.image&&cam.timestamp>(state.cameraFrameTs||0)){state.cameraFrameTs=cam.timestamp;if(state.source!=='camera'){state.crop={top:0,bottom:0,left:0,right:0};state.source='camera';$('setupDialog').close();toast('Live view connected.');}await setImage(cam.image,'camera',cam.timestamp);}if(cam.settingsTime&&cam.settingsTime>(state.cameraSettingsTs||0)){state.cameraSettingsTs=cam.settingsTime;state.cameraSettings=cam.settings||null;state.cameraSettingsAt=Date.now();applyCameraSettings(cam.settings);}}
if(native&&$('cameraConnectButton')){$('cameraConnectButton').onclick=()=>connectCamera('sony-wifi');if($('cameraUsbButton'))$('cameraUsbButton').onclick=()=>connectCamera('usb');if($('canonWifiButton'))$('canonWifiButton').onclick=()=>connectCamera('canon-wifi');$('cameraDisconnectButton').onclick=()=>{stopCapture();cameraButtons(false);$('cameraStatus').textContent='Disconnected from the camera.';status('Disconnected from the camera.');};try{const saved=parseNative('cameraSaved');if(saved.ssid)$('cameraSsid').value=saved.ssid;if(saved.hasPassword)$('cameraPassword').placeholder='Saved on this phone';}catch{}try{const cam=parseNative('cameraStatus','0');if(['connecting','live','waiting'].includes(cam.state)){state.cameraRequested=true;state.cameraKind=cam.kind==='usb'?'usb':cam.kind==='canon-wifi'?'canon-wifi':'sony-wifi';if($('cameraKind'))$('cameraKind').value=state.cameraKind;showKind();cameraButtons(true);}}catch{}setInterval(()=>{pollCamera().catch(()=>{});},250);}
// ---- One-time "What's new" card after an update
function noteSections(el,sections){el.replaceChildren();for(const sec of sections){if(sections.length>1){const h=document.createElement('li');h.className='notes-version';h.textContent='Framewise '+String(sec.version).replace(/\.0$/,'');el.append(h);}for(const n of sec.notes){const li=document.createElement('li');li.textContent=String(n);el.append(li);}}}
async function showWhatsNew(){let info;try{info=await (await fetch('whats-new.json',{cache:'no-store'})).json();}catch{return;}if(!info||typeof info.version!=='string'||!Array.isArray(info.notes))return;let seen=null,used=false;try{seen=localStorage.getItem('framewise.seenVersion');used=Boolean(seen||localStorage.getItem('framewise.preferences')||localStorage.getItem('framewise.log'));if(!seen||compareVersions(info.version,seen)>0)localStorage.setItem('framewise.seenVersion',info.version);}catch{return;}if(!used||(seen&&compareVersions(info.version,seen)<=0))return;const sections=notesSince(info,seen);if(!sections.length)return;$('whatsNewTitle').textContent=titleFor(info,sections,seen);noteSections($('whatsNewList'),sections);$('whatsNewDialog').showModal();}
if($('whatsNewDone'))$('whatsNewDone').onclick=()=>$('whatsNewDialog').close();
showWhatsNew();
window.onUpdateStatus=payload=>{try{applyUpdateStatus(typeof payload==='string'?JSON.parse(payload):payload);}catch{}};
if(native&&$('checkUpdateButton')){$('checkUpdateButton').onclick=()=>window.Android.checkForUpdates();$('installUpdateButton').onclick=()=>window.Android.installUpdate();$('releasePageButton').onclick=()=>{if(state.updateUrl)window.Android.openUrl(state.updateUrl);};$('updateBannerOpen').onclick=()=>{$('updateBanner').hidden=true;openSetup('updates');};$('updateBannerClose').onclick=()=>{$('updateBanner').hidden=true;};try{applyUpdateStatus(parseNative('getUpdateStatus'));}catch{}}
