// ---- Local shot history (stays on this phone)
function fmtSettings(x){const p=[];if(x.shutter)p.push(formatShutter(x.shutter));if(x.aperture)p.push('ƒ/'+x.aperture);if(x.iso)p.push('ISO '+x.iso);if(x.exposureCompensation!=null)p.push((x.exposureCompensation>0?'+':'')+x.exposureCompensation+' EV');if(x.mode)p.push(x.mode);if(x.whiteBalance)p.push('WB '+x.whiteBalance);return p.join(' · ');}
function renderHistory(){const box=$('historyList');if(!box)return;const list=loadHistory(localStorage);$('historyCount').textContent=`${list.length} shot${list.length===1?'':'s'} saved on this phone`;box.replaceChildren();for(const e of list.slice(0,100)){const div=document.createElement('div');div.className='session-entry';const t=document.createElement('time');t.textContent=new Date(e.at).toLocaleString()+(Number.isInteger(e.score)?` · score ${e.score}/10`:'');const set=document.createElement('p');set.className='micro';set.textContent=fmtSettings(e.settings||{})||'No settings recorded';const p=document.createElement('p');p.textContent=e.summary||'';div.append(t,set,p);if(e.tips&&e.tips.length){const ul=document.createElement('ul');for(const tip of e.tips){const li=document.createElement('li');li.textContent=tip;ul.append(li);}div.append(ul);}box.append(div);}}
if($('clearHistory'))$('clearHistory').onclick=()=>{clearHistory(localStorage);renderHistory();toast('Shot history cleared.');};
renderHistory();
// ---- Camera + connection picker (the Camera body setting is the single source of truth)
function kindsFor(body){return body==='Canon EOS 2000D'?['usb','canon-wifi']:['sony-wifi','usb'];}
function pickKind(body,current){const allowed=kindsFor(body);return allowed.includes(current)?current:allowed[0];}
function showKind(){const body=$('cameraBody')?$('cameraBody').value:'Sony a6100';const lbl=document.querySelector?document.querySelector('.camera-label'):null;if(lbl)lbl.textContent=body.startsWith('Canon')?'CANON EOS 2000D':'SONY α6100';const sel=$('cameraKind');if(sel){for(const o of sel.options)o.hidden=o.disabled=!kindsFor(body).includes(o.value);sel.value=pickKind(body,sel.value);}const kind=sel?sel.value:'sony-wifi';for(const el of document.querySelectorAll('[data-kind]'))el.hidden=el.dataset.kind!==kind;for(const el of document.querySelectorAll('[data-body-only]'))el.hidden=el.dataset.bodyOnly!==body;for(const b of document.querySelectorAll('[data-body]')){const on=b.dataset.body===body;b.classList.toggle('selected',on);b.setAttribute('aria-checked',String(on));}try{localStorage.setItem('framewise.cameraKind',kind);}catch{}}
function chooseBody(body){if(!$('cameraBody')||$('cameraBody').value===body){showKind();return;}$('cameraBody').value=body;if(body.startsWith('Canon')&&$('lensName').value!=='canon-kit')$('lensName').value='canon-kit';savePreferences();invalidate();showKind();}
for(const b of document.querySelectorAll('[data-body]'))b.onclick=()=>chooseBody(b.dataset.body);
if($('cameraBody'))$('cameraBody').addEventListener('change',()=>{savePreferences();showKind();});
if($('cameraKind')){try{const k=localStorage.getItem('framewise.cameraKind');if(['sony-wifi','usb','canon-wifi'].includes(k))$('cameraKind').value=k;}catch{}$('cameraKind').onchange=showKind;}
showKind();
// ---- Test reports: built here, shared only through Android's share sheet
function collectReport(){let nativePart={};try{nativePart=native?parseNative('nativeReport'):{};}catch{}let preferences={};try{preferences=JSON.parse(localStorage.getItem('framewise.preferences')||'{}');}catch{}const ui={cameraKind:state.cameraKind||($('cameraKind')&&$('cameraKind').value)||null,cameraModel:state.cameraModel||null,source:state.source,aiProvider:state.provider,aiConfigured:state.aiConfigured,lastStatus:$('activityStatus')?$('activityStatus').textContent:''};return buildReport({native:nativePart,history:loadHistory(localStorage),preferences,jsLog,ui});}
function shareReportAnotherWay(){if(!native){toast('Reports are sent from the Android app.');return;}const report=collectReport();window.Android.shareReport(JSON.stringify(report,null,1),summaryText(report));}
function sendReport(){if(!native){toast('Reports are sent from the Android app.');return;}if(typeof window.Android.uploadReport!=='function'){shareReportAnotherWay();return;}const report=fitReport(collectReport());if(!report){toast('This report is too big to send automatically. Use “Share another way”.');return;}if($('sendReportButton'))$('sendReportButton').disabled=true;status('Sending the test report…');window.Android.uploadReport(JSON.stringify(report));}
window.onReportError=message=>toast('Could not open the share sheet: '+message);
window.onReportSent=(result,message)=>{if($('sendReportButton'))$('sendReportButton').disabled=false;const text=result==='sent'?'Sent, thanks!':result==='queued'?'No internet right now. The report will be sent the next time Framewise opens.':(message||'The report could not be sent. Try “Share another way”.');status(text);toast(text);if($('reportResult'))$('reportResult').textContent=text;};
if($('shareReportButton'))$('shareReportButton').onclick=shareReportAnotherWay;
if($('sendReportButton'))$('sendReportButton').onclick=sendReport;
if($('previewReportButton'))$('previewReportButton').onclick=()=>{const pre=$('reportPreview');pre.textContent=JSON.stringify(collectReport(),null,1);pre.hidden=!pre.hidden;};
if($('clearReportButton'))$('clearReportButton').onclick=()=>{try{window.Android.clearDiagnostics();}catch{}jsLog.length=0;toast('Error log cleared.');};
if($('reportAuto')){try{$('reportAuto').checked=localStorage.getItem('framewise.reportAuto')!=='off';}catch{}$('reportAuto').onchange=()=>{try{localStorage.setItem('framewise.reportAuto',$('reportAuto').checked?'on':'off');}catch{}};}
if($('reportSendNow'))$('reportSendNow').onclick=()=>{$('reportDialog').close();sendReport();};
if($('reportLater'))$('reportLater').onclick=()=>$('reportDialog').close();
if(native){setTimeout(()=>{try{if(localStorage.getItem('framewise.reportAuto')==='off')return;const st=parseNative('reportStatus');if(!st.unreported)return;$('reportTitle').textContent=st.crashed?'Framewise closed unexpectedly last time.':'Framewise ran into an error.';if(!$('whatsNewDialog').open&&!$('reportDialog').open)$('reportDialog').showModal();}catch{}},1500);}
if($('aboutVersion')){try{$('aboutVersion').textContent=native?parseNative('getStatus').appVersion||'':'';}catch{}}

// Release focus after a touch tap so no highlight sticks around.
document.addEventListener('pointerup',e=>{if(e.pointerType==='mouse')return;const b=e.target.closest&&e.target.closest('button,summary,a');if(b)setTimeout(()=>b.blur(),150);},true);
